-- Actual installed identities/definitions and effective privileges, no conceptual aliases.
WITH roles AS (SELECT oid,rolname FROM pg_roles WHERE rolname LIKE 'mxas_%'),
functions AS (SELECT p.oid,p.oid::regprocedure::text AS identity,n.nspname,r.rolname AS owner,p.prosecdef,p.provolatile,p.proparallel,p.proleakproof,p.proconfig,p.proacl::text AS acl,pg_get_functiondef(p.oid) AS definition,encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex') AS definition_sha256,
 (SELECT jsonb_agg(jsonb_build_object('role',r2.rolname,'execute',has_function_privilege(r2.oid,p.oid,'EXECUTE')) ORDER BY r2.rolname) FROM roles r2) AS effective_execute,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',grantor::regrole::text,'grantee',CASE WHEN grantee=0 THEN 'PUBLIC' ELSE grantee::regrole::text END,'privilege',privilege_type,'grantable',is_grantable) ORDER BY grantee,privilege_type),'[]'::jsonb) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))) AS acl_entries
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_roles r ON r.oid=p.proowner WHERE n.nspname IN ('mixer_authz','mixer_hosted_release')),
relations AS (SELECT c.oid,n.nspname,c.relname,own.rolname AS owner,c.relrowsecurity,c.relforcerowsecurity,c.relacl::text AS acl,
 (SELECT jsonb_agg(jsonb_build_object('ordinal',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(ad.adbin,ad.adrelid),'collation',co.collname,'column_acl',a.attacl::text) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef ad ON ad.adrelid=a.attrelid AND ad.adnum=a.attnum LEFT JOIN pg_collation co ON co.oid=a.attcollation WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped) AS columns,
 (SELECT coalesce(jsonb_agg(jsonb_build_object('name',con.conname,'type',con.contype,'validated',con.convalidated,'deferrable',con.condeferrable,'initially_deferred',con.condeferred,'definition',pg_get_constraintdef(con.oid,true)) ORDER BY con.conname),'[]'::jsonb) FROM pg_constraint con WHERE con.conrelid=c.oid) AS constraints,
 (SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'select',has_table_privilege(r.oid,c.oid,'SELECT'),'insert',has_table_privilege(r.oid,c.oid,'INSERT'),'update',has_table_privilege(r.oid,c.oid,'UPDATE'),'delete',has_table_privilege(r.oid,c.oid,'DELETE'),'truncate',has_table_privilege(r.oid,c.oid,'TRUNCATE'),'references',has_table_privilege(r.oid,c.oid,'REFERENCES'),'column_update',(SELECT jsonb_agg(jsonb_build_object('column',a.attname,'allowed',has_column_privilege(r.oid,c.oid,a.attnum,'UPDATE')) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)) ORDER BY r.rolname) FROM roles r) AS effective_privileges
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles own ON own.oid=c.relowner WHERE n.nspname IN ('mixer_authz','mixer_hosted_release') AND c.relkind='r'),
composites AS (SELECT t.typname,n.nspname,own.rolname AS owner,t.typacl::text AS acl,(SELECT jsonb_agg(jsonb_build_object('ordinal',a.attnum,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod)) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=t.typrelid AND a.attnum>0 AND NOT a.attisdropped) AS fields FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace JOIN pg_roles own ON own.oid=t.typowner JOIN pg_class c ON c.oid=t.typrelid WHERE n.nspname='mixer_hosted_release' AND c.relkind='c'),
policies AS (SELECT * FROM pg_policies WHERE schemaname IN ('mixer_authz','mixer_hosted_release'))
SELECT jsonb_build_object('server_version',current_setting('server_version'),'functions',(SELECT jsonb_agg(to_jsonb(f)-'oid' ORDER BY identity) FROM functions f),'tables',(SELECT jsonb_agg(to_jsonb(t)-'oid' ORDER BY nspname,relname) FROM relations t),'composites',(SELECT jsonb_agg(to_jsonb(c) ORDER BY typname) FROM composites c),'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname) FROM policies p),'roles',(SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'superuser',r.rolsuper,'inherit',r.rolinherit,'create_role',r.rolcreaterole,'create_db',r.rolcreatedb,'can_login',r.rolcanlogin,'replication',r.rolreplication,'bypass_rls',r.rolbypassrls,'connection_limit',r.rolconnlimit,'valid_until',r.rolvaliduntil::text,'settings',r.rolconfig,'all_memberships',(SELECT coalesce(jsonb_agg(x.rolname ORDER BY x.rolname),'[]'::jsonb) FROM pg_roles x WHERE x.oid<>r.oid AND pg_has_role(r.oid,x.oid,'MEMBER'))) ORDER BY r.rolname) FROM pg_roles r WHERE r.rolname LIKE 'mxas_%'),'memberships',(SELECT coalesce(jsonb_agg(to_jsonb(m)),'[]'::jsonb) FROM pg_auth_members m WHERE m.roleid IN (SELECT oid FROM roles) OR m.member IN (SELECT oid FROM roles)),'schemas',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname,'owner',n.nspowner::regrole::text,'acl',n.nspacl::text,'effective',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'create',has_schema_privilege(r.oid,n.oid,'CREATE')) ORDER BY r.rolname) FROM roles r)) ORDER BY n.nspname) FROM pg_namespace n WHERE n.nspname IN ('mixer_authz','mixer_hosted_release','public')),'default_acls',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',d.defaclrole::regrole::text,'namespace',d.defaclnamespace,'object_type',d.defaclobjtype,'acl',d.defaclacl::text) ORDER BY d.defaclrole,d.defaclnamespace,d.defaclobjtype),'[]'::jsonb) FROM pg_default_acl d),'database',(SELECT jsonb_build_object('name',datname,'owner',datdba::regrole::text,'acl',datacl::text,'effective',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'connect',has_database_privilege(r.oid,d.oid,'CONNECT'),'create',has_database_privilege(r.oid,d.oid,'CREATE'),'temporary',has_database_privilege(r.oid,d.oid,'TEMP')) ORDER BY r.rolname) FROM roles r)) FROM pg_database d WHERE datname=current_database()));
